head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ15BM01';

scwin.param;

/* 물건명세서 doc ID */
scwin.gdsDspslDocId = ''

/* 사진갯수 */
scwin.currentIndex = 0;
scwin.itempPage = 5;

/* 회원ID */
scwin.lgnMbr = "";

/* 유사매각물건사례 */
scwin.aroundDspsltxt = "";

scwin.menuNm = ''
scwin.prevPgmId = '';
scwin.pageNum = '';


/* 2022 12 15 청구 금액 경우 TB_PGJ101(사건 마스터) 테이블 화폐 단위 컬럼이 추가 되어
청구 금액 부분에 화폐단위는 '원'이 아니라 해당 컬럼의 입력된 화폐단위로 보여준다.
이유는 청구 금액이 달러로도 들어올수 있다고 하여 수정됨. */

/**
 *
 * onPageLoad시 해당 물건의 상세 정보를 조회한다.
 *
 * 2022 12 15 청구 금액 경우 TB_PGJ101(사건 마스터) 테이블 화폐 단위 컬럼이 추가 되어
 * 청구 금액 부분에 화폐단위는 '원'이 아니라 해당 컬럼의 입력된 화폐단위로 보여준다.
 * 이유는 청구 금액이 달러로도 들어올수 있다고 하여 수정됨
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.13.   나해준                    [NELS]최초 생성
 *  2025.07.23.   강은숙                    [25A-PGJ-0018] 매각공고에서 물건조회시 오류 개선
 *  2025.08.06.   강은숙                    [25A-PGJ-0020] 매수보증금의 표시 개선
 *  2025.12.26.   공태은                    [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
 *  2026.01.28.   강은숙                    [26A-PGJ-0004] 물건상세조회 인근매각통계 조회 개선
 * ============= ============ ==========================
 */
scwin.onpageload = function () {

    /* 메뉴 구분코드에 따른 사이드 메뉴 세팅 */
    spn_gdsDtlSrchElctnTag.hide();
    scwin.param = $p.getParameter("param");
    scwin.prevPgmId = scwin.param.prevInfo?.prevPgmId;
    scwin.pageNum = scwin.param.prevInfo?.pageNum || 1;
    const sideDvsCd = scwin.param.srchInfo?.sideDvsCd;
    scwin.menuNm = scwin.param?.menuNm || scwin.param.srchInfo?.menuNm;

    scwin.lgnMbr = WebSquare.cookie.getCookie('cortAuctnLgnMbr') || 'NONUSER';
    scglblo.setScUserId(scwin.lgnMbr);
    scscrno.setScPgmId(scwin.pgmId);

    switch (sideDvsCd) {
        case '1':
            /* 2025.07.23. 강은숙  [25A-PGJ-0018] 매각공고에서 물건조회시 오류 개선*/
            tbx_mainTitle.setValue(scwin.menuNm)
            spn_gdsDtlDvsMenu1.setValue("경매공고")
            spn_gdsDtlDvsMenu2.setValue(scwin.menuNm)
            wfm_sideMenu.setSrc("../common/sideMenu/side001.xml")
            break;
        case '2':
            tbx_mainTitle.setValue(scwin.menuNm)
            spn_gdsDtlDvsMenu1.setValue("경매물건")
            spn_gdsDtlDvsMenu2.setValue(scwin.menuNm)
            wfm_sideMenu.setSrc("../common/sideMenu/side002.xml")
            break;
        case '3':
            tbx_mainTitle.setValue(scwin.menuNm)
            spn_gdsDtlDvsMenu1.setValue("나의경매")
            spn_gdsDtlDvsMenu2.setValue(scwin.menuNm);
            wfm_sideMenu.setSrc("../common/sideMenu/side006.xml")
            break;
        default:
            tbx_mainTitle.setValue('물건상세검색')
            spn_gdsDtlDvsMenu1.setValue("경매물건");
            spn_gdsDtlDvsMenu2.setValue('물건상세검색')
            wfm_sideMenu.setSrc("../common/sideMenu/side002.xml")
    }

    /* 메뉴 */
    // 2025.12.26. 공태은 [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
    if (!scutilo.isEmpty(scwin.prevPgmId)) {
        if(sideDvsCd == '3'){
            $p.main().wfm_mainFrame.scope.wfm_sideMenu.scope.scwin.menuFocus('PGJ195');
        }else{
            $p.main().wfm_mainFrame.scope.wfm_sideMenu.scope.scwin.menuFocus(scwin.prevPgmId.slice(0, 6));
        }
    }

    grp_lstDtsLimtMax.hide();
    grp_lstDtsLimtMin.hide();
    tac_aroundGdsExmGrp.hide();  //2026.01.28. 강은숙  [26A-PGJ-0004]인근매각물건사례 처음 안보이게

    dma_srchGdsDtlSrch.setJSON(scwin.param);
    com.executeSubmission(sbm_selectGdsDtlSrchDtlInfo);
};

scwin.onpageunload = function () {

};

//웹접근성으로 인한 title제공 수정
scwin.titleFormatter = function () {
    return "";
}

/**
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ =========================
 *  2023.03.13.   나해준       [NELS]최초 생성
 *  2025.08.06.   강은숙       [25A-PGJ-0020] 매수보증금의 표시 개선
 *  2026.01.28.   강은숙       [26A-PGJ-0004] 물건상세조회 인근매각통계 조회 개선
 * ============= ============ ==========================
 */
scwin.sbm_selectGdsDtlSrchDtlInfo_submitdone = function (e) {
    document.body.scrollTop = 0;
    const ipcheck = e.responseJSON.data.ipcheck; /* 로봇탐지 */
    if (ipcheck) {
        //매각물건 명세서 버튼은 입찰구분코드가 존재할시에 보여준다.
        btn_dspslGdsSpcfc1.hide();
        btn_dspslGdsSpcfc2.hide();
        // 법원 사무소명
        spn_gdsDtlSrchCondCortNm.setValue(pgjUtil.getCortOfcNm("B", scwin.param.cortOfcCd))

        // 사건기본정보
        const csBaseInfo = dma_result.get('csBaseInfo');
        // 사건번호
        let printCsNo = csBaseInfo.userCsNo
        spn_gdsDtlSrchCondCsNo.setValue(printCsNo);

        // 사건의 사진구분별건수 조회
        const picDvsIndvdCnt = dma_result.get('picDvsIndvdCnt');
        // 사건의 사진리스트 조회
        const csPicLst = dma_result.get('csPicLst');
        // 물건의 매각기일리스트
        const dspslGdsDxdyInfo = dma_result.get('dspslGdsDxdyInfo');
        // 매각목적물리스트
        const gdsDspslObjctLst = dma_result.get('gdsDspslObjctLst');
        // 배당요구종기일
        const dstrtDemnInfo = dma_result.get('dstrtDemnInfo');
        // 물건 매각 기일리스트
        const gdsDspslDxdyLst = dma_result.get('gdsDspslDxdyLst');
        // 대지권토지 리스트
        const rgltLandLstAll = dma_result.get('rgltLandLstAll');
        // 건물표제부사세 리스트
        const bldSdtrDtlLstAll = dma_result.get('bldSdtrDtlLstAll');
        // 제시외 건물리스트
        const gdsNotSugtBldLsstAll = dma_result.get('gdsNotSugtBldLsstAll');
        // 매각목적물의 부동산소재지번 리스트
        const gdsRletStLtnoLstAll = dma_result.get('gdsRletStLtnoLstAll');
        // 감정평가요항서
        const aeeWevlMnpntLst = dma_result.get('aeeWevlMnpntLst');
        // 유사인근매각통계
        const aroundDspslStats = dma_result.get('aroundDspslStats');

        // 주석시작 ===========================================

        /* 상세내역 사건번호 */
        spn_gdsDtlSrchUserCsNo.setValue(csBaseInfo.userCsNo);
        //소송 구분코드가 '2'일경우 전자 표시
        if (!scutilo.isEmpty(csBaseInfo.lwstDvsCd) && '2' === csBaseInfo.lwstDvsCd) {
            spn_gdsDtlSrchElctnTag.show("");
        }

        /* 상세내역 물건번호 */
        spn_gdsDtlSrchGdsSeq.setValue(dspslGdsDxdyInfo.dspslGdsSeq)
        /* 상세내역 물건종류 */
        spn_gdsDtlSrchGdsKnd.setValue(pgjUtil.getSTGcodeSystemNm('PGJ', 'AUCTN_GDS_USG_CD', dspslGdsDxdyInfo.auctnGdsUsgCd))
        /* 상세내역 감정평가금액 */
        spn_gdsDtlSrchAeeEvlAmt.setValue(!scutilo.isEmpty(dspslGdsDxdyInfo.aeeEvlAmt) ? dspslGdsDxdyInfo.aeeEvlAmt : "0");
        /* 최저 매각가격, 매수신청보증금 시작 */
        let lwsPrc = "";
        if (!scutilo.isEmpty(dspslGdsDxdyInfo.scndPbancLwsDspslPrc)) {
            let sPrchDposRate = Number(dspslGdsDxdyInfo.prchDposRate); //[25A-PGJ-0020] 매수보증금비율
            //1차
            lwsPrc = `<img src='/pgj/cm/images/contents/number_01.gif' style="margin:3px;">${scutilo.getCommaFmt(dspslGdsDxdyInfo.fstPbancLwsDspslPrc)}원<br />`
            lwsPrc += `(${scutilo.getCommaFmt(Math.ceil((Number(dspslGdsDxdyInfo.fstPbancLwsDspslPrc) * sPrchDposRate / 100) / 100) * 100)}원)<br />`
            //2차
            lwsPrc += `<img src='/pgj/cm/images/contents/number_02.gif' style="margin:3px;">${scutilo.getCommaFmt(dspslGdsDxdyInfo.scndPbancLwsDspslPrc)}원<br />`
            lwsPrc += `(${scutilo.getCommaFmt(Math.ceil((Number(dspslGdsDxdyInfo.scndPbancLwsDspslPrc) * sPrchDposRate / 100) / 100) * 100)}원)`
            if (!scutilo.isEmpty(dspslGdsDxdyInfo.thrdPbancLwsDspslPrc)) {
                lwsPrc += `<br /><img src='/pgj/cm/images/contents/number_03.gif' style="margin:3px;">${scutilo.getCommaFmt(dspslGdsDxdyInfo.thrdPbancLwsDspslPrc)}원`
                lwsPrc += `<br />(${scutilo.getCommaFmt(Math.ceil((Number(dspslGdsDxdyInfo.thrdPbancLwsDspslPrc) * sPrchDposRate / 100) / 100) * 100)}원)`
                if (!scutilo.isEmpty(dspslGdsDxdyInfo.fothPbancLwsDspslPrc)) {
                    lwsPrc += `<br /><img src='/pgj/cm/images/contents/number_04.gif' style="margin:3px;">${scutilo.getCommaFmt(dspslGdsDxdyInfo.fothPbancLwsDspslPrc)}원`
                    lwsPrc += `<br />(${scutilo.getCommaFmt(Math.ceil((Number(dspslGdsDxdyInfo.fothPbancLwsDspslPrc) * sPrchDposRate / 100) / 100) * 100)}원)`
                }
            }
        } else {
            if (!scutilo.isEmpty(dspslGdsDxdyInfo.fstPbancLwsDspslPrc)) {
                let sPrchDposRate = Number(dspslGdsDxdyInfo.prchDposRate); //[25A-PGJ-0020] 매수보증금비율
                lwsPrc = `${scutilo.getCommaFmt(dspslGdsDxdyInfo.fstPbancLwsDspslPrc)}원<br />`
                lwsPrc += `(${scutilo.getCommaFmt(Math.ceil((Number(dspslGdsDxdyInfo.fstPbancLwsDspslPrc) * sPrchDposRate / 100) / 100) * 100)}원)`

            } else {
                lwsPrc = '0 원<br />(0 원)'
            }
        }
        spn_gdsDtlSrchlwsDspsl.setValue(lwsPrc)

        /* 입찰구분 */
        spn_gdsDtlSrchBidDvs.setValue(pgjUtil.getSTGcodeSystemNm('PGJ', 'BID_DVS_CD', dspslGdsDxdyInfo.bidDvsCd))
        /* 매각기일 */
        let dxdy = ""
        if ("1" === dspslGdsDxdyInfo.realMulKind) {
            spn_gdsDtlSrchDspslDxdyTitile.setValue('매각기일')
        } else {
            spn_gdsDtlSrchDspslDxdyTitile.setValue('예정매각기일')
        }
        dxdy = scdateo.getFmtDate(dspslGdsDxdyInfo.dspslDxdyYmd, ".");
        if (!scutilo.isEmpty(dspslGdsDxdyInfo.bidBgngYmd)) {
            dxdy += `(입찰기간: ${scdateo.getFmtDate(dspslGdsDxdyInfo.bidBgngYmd, ".")} ~ ${scdateo.getFmtDate(dspslGdsDxdyInfo.bidEndYmd, ".")})`
        }
        dxdy += ` ${scwin.timeFormat(dspslGdsDxdyInfo.fstDspslHm)} ${dspslGdsDxdyInfo.dspslPlcNm}`
        spn_gdsDtlSrchDspslDxdy.setValue(dxdy);

        /* 물건 비고 */
        // 구문을 나누기 위해서 escape를 fasle로 설정
        if (!scutilo.isEmpty(dspslGdsDxdyInfo.dspslGdsRmk)) {
            var dspslGdsRmk = dspslGdsDxdyInfo.dspslGdsRmk.replaceAll('\n', '<br>');
            spn_gdsDtlSrchRmk.setValue(dspslGdsRmk);
        } else {
            spn_gdsDtlSrchRmk.setValue("");
        }

        // 목록 소재지 생성
        if (gdsDspslObjctLst.length > 0) {
            for (let i = 0; i < gdsDspslObjctLst.length; i++) {
                let st = "";
                gen_lstSt.insertChild(i);
                // 목록 소재지 타이틀
                gen_lstSt.getChild(i, 'spn_gdsDtlSrchStTitle').setValue(`목록${gdsDspslObjctLst[i].dspslObjctSeq} 소재지`);
                // 목록 소재지 내용
                if (!scutilo.isEmpty(gdsDspslObjctLst[i].sclDspslGdsLstUsgCd)
                    && (gdsDspslObjctLst[i].sclDspslGdsLstUsgCd.substring(3) != '99' || gdsDspslObjctLst[i].sclDspslGdsLstUsgCd.substring(3) != '98')) {
                    st = `(${pgjUtil.getSTGcodeSystemNm('PGJ', 'DSPSL_GDS_LST_USG_CD', gdsDspslObjctLst[i].sclDspslGdsLstUsgCd)}) `
                }
                st += gdsDspslObjctLst[i].userPrintSt
                gen_lstSt.getChild(i, 'spn_gdsDtlSrchStCtt').setValue(st);
                // 등기기록 열람 조건에 따라 등기기록 열람 버튼 숨기기
                if (gdsDspslObjctLst[i].rgstRdngYn === 'N') { //현재 테스트중
                    gen_lstSt.getChild(i, 'btn_gdsDtlSrchRgstRdngBtn').hide();
                } else {
                    //등기기록 열람 조건이 Y일경우 핀번호 전달
                    gen_lstSt.getChild(i, 'btn_gdsDtlSrchRgstRdngBtn').setUserData('carUnqNo', gdsDspslObjctLst[i].objctRletCarUnqNo);
                }
                //전자지도 보기
                gen_lstSt.getChild(i, "btn_map").setUserData('x', gdsDspslObjctLst[i].stXcrd);
                gen_lstSt.getChild(i, "btn_map").setUserData('y', gdsDspslObjctLst[i].stYcrd);
                // 씨리얼 (토지이용계획) 버튼에 본 번호 저장
                gen_lstSt.getChild(i, "btn_landUtilPlan").setUserData('pnuNoCtt', gdsDspslObjctLst[i].pnuNoCtt);

            }
        }

        /* 담당 */
        spn_gdsDtlSrchCortNm.setValue(csBaseInfo.cortOfcNm)
        if (csBaseInfo.cortTypCd === '40') { //지법
            spn_gdsDtlSrchCortSptNm.setValue("");
        } else if (csBaseInfo.cortTypCd === '70') { //지원
            spn_gdsDtlSrchCortSptNm.setValue(` ${csBaseInfo.cortSptNm.replace("대구", "").replace("부산", "")}`)
        }
        spn_cortAuctnJdbnNm.setValue('| ' + csBaseInfo.cortAuctnJdbnNm);

        /* 사건 접수 일자 */
        spn_gdsDtlSrchCsRcptYmd.setValue(scdateo.getFmtDate(csBaseInfo.csRcptYmd, '.'));

        /*  경매개시일*/
        spn_gdsDtlSrchAuctnStrtDay.setValue(scdateo.getFmtDate(csBaseInfo.csCmdcYmd, '.'));

        /* 배당요구종기 */
        if (dstrtDemnInfo.length > 0) {
            let dstrtDemnLstprdDay = "";
            for (let i = 0; i < dstrtDemnInfo.length; i++) {
                if (!scutilo.isEmpty(dstrtDemnInfo[i].dstrtDemnLstprdYmd)) {
                    dstrtDemnLstprdDay += scdateo.getFmtDate(dstrtDemnInfo[i].dstrtDemnLstprdYmd, '.');
                }
                if (!scutilo.isEmpty(dstrtDemnInfo[i].orddcsDvsCd) && dstrtDemnInfo[i].orddcsDvsCd === '022') {
                    dstrtDemnLstprdDay += '(연기)'
                }
                dstrtDemnLstprdDay += (i >= 0 && i !== (dstrtDemnInfo.length - 1)) ? '/' : ""
                dstrtDemnLstprdDay += ((i % 2) == 1 && (i !== (dstrtDemnInfo.length - 1))) ? '<br />' : ""
            }
            spn_gdsDtlSrchDstrtDemnLstprd.setValue(dstrtDemnLstprdDay)

        }

        /* 청구 금액 */
        if (!scutilo.isEmpty(csBaseInfo.clmAmt)) {
            spn_gdsDtlSrchClmAmt.setValue(csBaseInfo.clmAmt);
        }
        /* 관련사진 */
        if (csPicLst.length > 0) {
            let cnt = 1;
            for (let i = scwin.currentIndex; i < scwin.currentIndex + scwin.itempPage && i < csPicLst.length; i++) {
                gen_pic.insertChild(i);
                gen_pic.getChild(i, "img_reltPic").setUserData('cortAuctnPicDvsCd', csPicLst[i].cortAuctnPicDvsCd)
                gen_pic.getChild(i, "img_reltPic").setUserData('cortAuctnPicSeq', csPicLst[i].cortAuctnPicSeq)
                gen_pic.getChild(i, "img_reltPic").setUserData('pageSeq', csPicLst[i].pageSeq)
                gen_pic.getChild(i, "img_reltPic").setUserData('cortOfcCd', csPicLst[i].cortOfcCd)
                gen_pic.getChild(i, "img_reltPic").setUserData('csNo', csPicLst[i].csNo)
                gen_pic.getChild(i, "img_reltPic").setSrc("data:image/png;base64," + csPicLst[i].picFile)

                /* 이미지 alt 처리 */
                const imgId = gen_pic.getChild(i, "img_reltPic").id
                const altNm = `${pgjUtil.getSTGcodeSystemNm('PGJ', 'CORT_AUCTN_PIC_DVS_CD', csPicLst[i].cortAuctnPicDvsCd)}_${cnt}`
                document.getElementById(imgId).setAttribute("alt", altNm)

                /* keyUp 이벤트 처리 */
                const imgTagId = gen_pic.getChild(i, "grp_imgPopup").id
                document.getElementById(imgTagId).setAttribute("href", "#")
                document.getElementById(imgTagId).addEventListener("keyup", (e) => {
                    if (e.code === 'Enter') scwin.img_reltPic_onclick(imgTagId)
                })
                cnt++
            }
        } else {
            grp_picLst.hide();
        }

        const toDay = Number(WebSquare.date.getCurrentServerDate());
        // 매각기일 일주일 전
        let prevSevenDspslDxdy = 0
        // 입찰기간 일주일전
        let prevSavenBidBandDxdy = 0
        let bidBgngYmdTemp = 0;
        let bidEndYmdTemp = 0;
        //매각기일
        const dspslDxdy = dspslGdsDxdyInfo.dspslDxdyYmd
        const bidBgngYmd = dspslGdsDxdyInfo.bidBgngYmd
        const bidEndYmd = dspslGdsDxdyInfo.bidEndYmd
        // let MseoViewDate = 7; // 20160427 강은숙 [16A-AIS-0021] 매각물건명세서 보여주는 기간

        // //20170420 강은숙 [17A-AIS-0012]대통령선거 임시공휴일 지정에 따른 공고기간 변경
        // //20170906 강은숙 [17A-AIS-0028]10월2일 임시공휴일 지정에 따른 공고기간 변경
