                                        if (!titleFlag) {
                                            titleFlag = true;
                                            dtlDts += `&nbsp;&nbsp;&nbsp;&nbsp;대지권의 비율:`
                                        } else {
                                            dtlDts += `&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;`
                                            dtlDts += `&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;`
                                        }
                                        if ((realRgltLandLst[j].rgltRateDnmnVal !== 0) && (realRgltLandLst[j].rgltRateNmrtVal !== 0)) {
                                            dtlDts += `${realRgltLandLst[j].rgltLandNo}. ${realRgltLandLst[j].rgltRateDnmnVal} 분의 ${realRgltLandLst[j].rgltRateNmrtVal}<br />`
                                        }
                                    }
                                }
                            }
                            titleFlag = false;
                        }
                    }
                } // 집합건물 끝
                if (!scutilo.isEmpty(gdsDspslObjctLst[i].dspslStkCtt)) { //매각지분이 있을경우
                    dtlDts += `<br /><br />매각지분 : ${gdsDspslObjctLst[i].dspslStkCtt}<br />`
                }
                if (!scutilo.isEmpty(realGdsNotSugtBldLsst) && realGdsNotSugtBldLsst.length > 0) {
                    let sugtBldCnt = 0;
                    for (let jdx = 0; jdx < realGdsNotSugtBldLsst.length; jdx++) {
                        if (gdsDspslObjctLst[i].dspslObjctSeq === realGdsNotSugtBldLsst[jdx].dspslObjctSeq) {
                            if (sugtBldCnt === 0) {
                                dtlDts += `<br /><br /> 제시외<br />`
                            }
                            sugtBldCnt++
                            dtlDts += `${realGdsNotSugtBldLsst[jdx].sugtBsdsBldSeq}.`
                            if (!scutilo.isEmpty(realGdsNotSugtBldLsst[jdx].etcUsgCtt)) {
                                dtlDts += `(용도)${realGdsNotSugtBldLsst[jdx].etcUsgCtt}`
                            }
                            if (!scutilo.isEmpty(realGdsNotSugtBldLsst[jdx].bldStrcDts)) {
                                dtlDts += `(구조)${realGdsNotSugtBldLsst[jdx].bldStrcDts}`
                            }
                            if (!scutilo.isEmpty(realGdsNotSugtBldLsst[jdx].bldArDts)) {
                                dtlDts += `(면적)${realGdsNotSugtBldLsst[jdx].bldArDts}`
                            }
                            dtlDts += `<br />`
                        }

                    }
                }
                if (gdsDspslObjctLst[i].auctnLstDvsCd === '05' || gdsDspslObjctLst[i].auctnLstDvsCd === '07' || gdsDspslObjctLst[i].auctnLstDvsCd === '12') { //건설기계, 항공기일 경우
                    dtlDts += `등록번호: ${!scutilo.isEmpty(gdsDspslObjctLst[i].objctRletCarUnqNo) ? gdsDspslObjctLst[i].objctRletCarUnqNo : ""}<br />`
                    dtlDts += `기종: ${!scutilo.isEmpty(gdsDspslObjctLst[i].bldNm) ? gdsDspslObjctLst[i].bldNm : ""}<br />`
                    if (!scutilo.isEmpty(gdsDspslObjctLst[i].bldDtlDts)) {
                        let splitTemp = gdsDspslObjctLst[i].bldDtlDts.split("\n");
                        splitTemp.forEach(data => dtlDts += `${data}<br />`);
                    }

                }
                if (gdsDspslObjctLst[i].auctnLstDvsCd === '08') { //광업권일경우
                    dtlDts += `등록번호: ${!scutilo.isEmpty(gdsDspslObjctLst[i].objctRletCarUnqNo) ? gdsDspslObjctLst[i].objctRletCarUnqNo : ""}<br />`
                    dtlDts += `광물명칭: ${!scutilo.isEmpty(gdsDspslObjctLst[i].bldNm) ? gdsDspslObjctLst[i].bldNm : ""}<br />`
                    if (!scutilo.isEmpty(gdsDspslObjctLst[i].bldDtlDts)) {
                        let splitTemp = gdsDspslObjctLst[i].bldDtlDts.split("\n");
                        splitTemp.forEach(data => dtlDts += `${data}<br />`);
                    }
                }
                if (gdsDspslObjctLst[i].auctnLstDvsCd === '09') { //어업권일경우
                    dtlDts += `번호: ${!scutilo.isEmpty(gdsDspslObjctLst[i].objctRletCarUnqNo) ? gdsDspslObjctLst[i].objctRletCarUnqNo : ""}<br />`
                    dtlDts += `어업및어구의명칭: ${!scutilo.isEmpty(gdsDspslObjctLst[i].bldNm) ? gdsDspslObjctLst[i].bldNm : ""}<br />`
                    if (!scutilo.isEmpty(gdsDspslObjctLst[i].bldDtlDts)) {
                        let splitTemp = gdsDspslObjctLst[i].bldDtlDts.split("\n");
                        splitTemp.forEach(data => dtlDts += `${data}<br />`);
                    }
                }
                if (gdsDspslObjctLst[i].auctnLstDvsCd === '99') { //기타일경우
                    dtlDts += `등록번호: ${!scutilo.isEmpty(gdsDspslObjctLst[i].objctRletCarUnqNo) ? gdsDspslObjctLst[i].objctRletCarUnqNo : ""}<br />`
                    dtlDts += `정류: ${!scutilo.isEmpty(gdsDspslObjctLst[i].bldNm) ? gdsDspslObjctLst[i].bldNm : ""}<br />`
                    if (!scutilo.isEmpty(gdsDspslObjctLst[i].bldDtlDts)) {
                        let splitTemp = gdsDspslObjctLst[i].bldDtlDts.split("\n");
                        splitTemp.forEach(data => dtlDts += `${data}<br />`);
                    }
                }
                //건물내역 표시 부분
                var escapeTxt = dtlDts.replace(/&nbsp;/g, ' ').replace(/<br\s*\/?>/gi, '\n');
                dlt_lstDts.setCellData(i, 'dtlDts', escapeTxt);

            }// 목록내역그리드 (상세내역 끝)
        } else { // 목록내역 끝
            grp_lstDtsLimtMax.show(""); //목록내역 50건이상일경우는 팝업창 오픈
        }

        //감정평가요항서
        gen_aeeEvlMnpntCtt.removeAll();//초기화
        if ( aeeWevlMnpntLst.length > 0 ) {
            let tempCd = "";
            let cnt = 1;
            let tempCnt = 1;
            let titleCnt = 1;
            for (let i = 0; i < aeeWevlMnpntLst.length; i++) {
                if (aeeWevlMnpntLst[i].aeeWevlMnpntTbltDvsCd !== tempCd) {
                    tempCnt = 1;
                    titleCnt = 1;
                    for (let j = 0; j < aeeWevlMnpntLst.length; j++) {
                        if (aeeWevlMnpntLst[i].aeeWevlMnpntTbltDvsCd === aeeWevlMnpntLst[j].aeeWevlMnpntTbltDvsCd) {
                            gen_aeeEvlMnpntCtt.insertChild(j);
                            gen_aeeEvlMnpntCtt.getChild(j, 'tbx_aeeEvlMnpntTitle').hide();
                            if (titleCnt == 1) { //감정평가요항서 요약 타이틀
                                gen_aeeEvlMnpntCtt.getChild(j, 'tbx_aeeEvlMnpntTitle').show();
                                gen_aeeEvlMnpntCtt.getChild(j, 'tbx_aeeEvlMnpntTitle').setValue(`${cnt}. ${pgjUtil.getSTGcodeSystemNm('PGJ', 'AEE_WEVL_MNPNT_TBLT_DVS_CD', aeeWevlMnpntLst[i].aeeWevlMnpntTbltDvsCd)}`)
                                titleCnt++;
                            }
                            gen_aeeEvlMnpntCtt.getChild(j, 'tbx_aeeEvlMnpntCttTitle').setValue(`${tempCnt++}) ${pgjUtil.getSTGcodeSystemNm('PGJ', 'AEE_WEVL_MNPNT_ITM_CD', aeeWevlMnpntLst[j].aeeWevlMnpntItmCd)}`)
                            let aeeWevlMnpntCtt = "";
                            if (scutilo.isEmpty(aeeWevlMnpntLst[j].aeeWevlMnpntCtt)) {
                                aeeWevlMnpntCtt = "-"
                            } else {
                                aeeWevlMnpntCtt = aeeWevlMnpntLst[j].aeeWevlMnpntCtt.replaceAll('\n', '<br>');
                            }
                            gen_aeeEvlMnpntCtt.getChild(j, 'tbx_aeeEvlMnpntCtt').setValue(aeeWevlMnpntCtt);
                        }
                    }
                    cnt++;
                }
                tempCd = aeeWevlMnpntLst[i].aeeWevlMnpntTbltDvsCd;
            }
        } else {
            gen_aeeEvlMnpntCtt.insertChild(0);
            gen_aeeEvlMnpntCtt.getChild(0, 'tbx_aeeEvlMnpntTitle').show();
            gen_aeeEvlMnpntCtt.getChild(0, 'tbx_aeeEvlMnpntTitle').setValue("2008년8월18일 이전에 감정평가완료된 물건에 대해서는 본 정보를 제공하지 않습니다. <br />감정평가서를 참조하시기 바랍니다.");
        }

        // 인근유사매각통계
        const lclDspslGdsLstUsgCd = gdsDspslObjctLst[0].lclDspslGdsLstUsgCd;
        /*  2026.01.28.   강은숙               [26A-PGJ-0004] 최초 조회했을때 인근매각통계 조회되지 않게 처리함
        if (!scutilo.isEmpty(aroundDspslStats) && lclDspslGdsLstUsgCd != "30000") {
            dlt_aroundDspslStats.insertRow(0)
            dlt_aroundDspslStats.insertRow(1)
            dlt_aroundDspslStats.insertRow(2)
            dlt_aroundDspslStats.setCellData(0, "dspslMonth", "3개월");
            dlt_aroundDspslStats.setCellData(1, "dspslMonth", "6개월");
            dlt_aroundDspslStats.setCellData(2, "dspslMonth", "12개월");
            dlt_aroundDspslStats.setCellData(0, "dspslCnt", `${!scutilo.isEmpty(aroundDspslStats[0].term3MgakCnt) ? aroundDspslStats[0].term3MgakCnt : 0}건`)
            dlt_aroundDspslStats.setCellData(1, "dspslCnt", `${!scutilo.isEmpty(aroundDspslStats[0].term6MgakCnt) ? aroundDspslStats[0].term6MgakCnt : 0}건`)
            dlt_aroundDspslStats.setCellData(2, "dspslCnt", `${!scutilo.isEmpty(aroundDspslStats[0].term12MgakCnt) ? aroundDspslStats[0].term12MgakCnt : 0}건`)
            dlt_aroundDspslStats.setCellData(0, "aeeEvlAmt", `${!scutilo.isEmpty(aroundDspslStats[0].term3AvgGamEvalAmt) ? scutilo.getCommaFmt(aroundDspslStats[0].term3AvgGamEvalAmt) : 0}원`)
            dlt_aroundDspslStats.setCellData(1, "aeeEvlAmt", `${!scutilo.isEmpty(aroundDspslStats[0].term6AvgGamEvalAmt) ? scutilo.getCommaFmt(aroundDspslStats[0].term6AvgGamEvalAmt) : 0}원`)
            dlt_aroundDspslStats.setCellData(2, "aeeEvlAmt", `${!scutilo.isEmpty(aroundDspslStats[0].term12AvgGamEvalAmt) ? scutilo.getCommaFmt(aroundDspslStats[0].term12AvgGamEvalAmt) : 0}원`)
            dlt_aroundDspslStats.setCellData(0, "dspslAmt", `${!scutilo.isEmpty(aroundDspslStats[0].term3AvgMgakPrc) ? scutilo.getCommaFmt(aroundDspslStats[0].term3AvgMgakPrc) : 0}원`)
            dlt_aroundDspslStats.setCellData(1, "dspslAmt", `${!scutilo.isEmpty(aroundDspslStats[0].term6AvgMgakPrc) ? scutilo.getCommaFmt(aroundDspslStats[0].term6AvgMgakPrc) : 0}원`)
            dlt_aroundDspslStats.setCellData(2, "dspslAmt", `${!scutilo.isEmpty(aroundDspslStats[0].term12AvgMgakPrc) ? scutilo.getCommaFmt(aroundDspslStats[0].term12AvgMgakPrc) : 0}원`)
            dlt_aroundDspslStats.setCellData(0, "dspslPrcRate", `${!scutilo.isEmpty(aroundDspslStats[0].term3MgakPrcRate) ? aroundDspslStats[0].term3MgakPrcRate : 0}%`)
            dlt_aroundDspslStats.setCellData(1, "dspslPrcRate", `${!scutilo.isEmpty(aroundDspslStats[0].term6MgakPrcRate) ? aroundDspslStats[0].term6MgakPrcRate : 0}%`)
            dlt_aroundDspslStats.setCellData(2, "dspslPrcRate", `${!scutilo.isEmpty(aroundDspslStats[0].term12MgakPrcRate) ? aroundDspslStats[0].term12MgakPrcRate : 0}%`)
            dlt_aroundDspslStats.setCellData(0, "flbdNcnt", `${!scutilo.isEmpty(aroundDspslStats[0].term3AvgFlbdNcnt) ? aroundDspslStats[0].term3AvgFlbdNcnt : 0}회`)
            dlt_aroundDspslStats.setCellData(1, "flbdNcnt", `${!scutilo.isEmpty(aroundDspslStats[0].term6AvgFlbdNcnt) ? aroundDspslStats[0].term6AvgFlbdNcnt : 0}회`)
            dlt_aroundDspslStats.setCellData(2, "flbdNcnt", `${!scutilo.isEmpty(aroundDspslStats[0].term12AvgFlbdNcnt) ? aroundDspslStats[0].term12AvgFlbdNcnt : 0}회`)
        }
        */

        let tmpCtt = "";
        if (lclDspslGdsLstUsgCd != "30000") {
            let adongSdNm = gdsDspslObjctLst[0].adongSdNm;
            let adongSggNm = gdsDspslObjctLst[0].adongSggNm;
            let auctnGdsUsgNm = pgjUtil.getSTGcodeSystemNm('PGJ', 'AUCTN_GDS_USG_CD', dspslGdsDxdyInfo.auctnGdsUsgCd);
            tmpCtt = "유사매각물건사례는 " + "'" + adongSdNm + " " + adongSggNm + " 중 " + auctnGdsUsgNm + "'" + "를 조건으로 하는 물건을 대상으로 작성되었습니다.";
        } else {
            tbx_dspslStatsAttn.hide();
            tmpCtt = "물건이 선박, 항공기, 권리에 해당하는 경우, 주소지 정보의 특성으로 인해 인근매각물건사례 정보를 제공하지 않습니다.";
        }
        scwin.aroundDspsltxt = tmpCtt;
        tbx_dspslStatsAttnMtr.setValue(tmpCtt);

    } else {
        scutilo.showMsg(scglblo.MSG.ERROR, e.responseJSON.message, () => {
            $p.url("/pgj/ui/pgj100/PGJ111M01.xml");
        });
    }
};


