/**
 * 사진 이전 버튼 클릭시 이동하는 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.25.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_prev_onclick = function () {
    gen_pic.removeAll();
    const csPicLst = dma_result.get('csPicLst');
    scwin.currentIndex -= scwin.itempPage;
    //사진셋  갯수
    if (csPicLst.length > 0) {
        if (scwin.currentIndex < 0) scwin.currentIndex = Math.floor((csPicLst.length - 1) / scwin.itempPage) * scwin.itempPage;
        let cnt = 0;
        for (let i = scwin.currentIndex; i < scwin.currentIndex + scwin.itempPage && i < csPicLst.length; i++) {
            gen_pic.insertChild(cnt);
            gen_pic.getChild(cnt, "img_reltPic").setUserData('cortAuctnPicDvsCd', csPicLst[i].cortAuctnPicDvsCd)
            gen_pic.getChild(cnt, "img_reltPic").setUserData('cortAuctnPicSeq', csPicLst[i].cortAuctnPicSeq)
            gen_pic.getChild(cnt, "img_reltPic").setUserData('pageSeq', csPicLst[i].pageSeq)
            gen_pic.getChild(cnt, "img_reltPic").setUserData('cortOfcCd', csPicLst[i].cortOfcCd)
            gen_pic.getChild(cnt, "img_reltPic").setUserData('csNo', csPicLst[i].csNo)
            gen_pic.getChild(cnt, "img_reltPic").setSrc("data:image/png;base64," + csPicLst[i].picFile)
            cnt++;
        }
    } else {
        return
    }
}


/**
 * 사진 다음 버튼 클릭시 이동하는 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.25.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_next_onclick = function () {
    gen_pic.removeAll();
    //사진셋  갯수
    let csPicLst = dma_result.get('csPicLst');
    scwin.currentIndex += scwin.itempPage
    if (csPicLst.length > 0) {
        if (scwin.currentIndex >= csPicLst.length) scwin.currentIndex = 0;
        let cnt = 0;
        for (let i = scwin.currentIndex; i < scwin.currentIndex + scwin.itempPage && i < csPicLst.length; i++) {
            gen_pic.insertChild(cnt);
            gen_pic.getChild(cnt, "img_reltPic").setUserData('cortAuctnPicDvsCd', csPicLst[i].cortAuctnPicDvsCd)
            gen_pic.getChild(cnt, "img_reltPic").setUserData('cortAuctnPicSeq', csPicLst[i].cortAuctnPicSeq)
            gen_pic.getChild(cnt, "img_reltPic").setUserData('pageSeq', csPicLst[i].pageSeq)
            gen_pic.getChild(cnt, "img_reltPic").setUserData('cortOfcCd', csPicLst[i].cortOfcCd)
            gen_pic.getChild(cnt, "img_reltPic").setUserData('csNo', csPicLst[i].csNo)
            gen_pic.getChild(cnt, "img_reltPic").setSrc("data:image/png;base64," + csPicLst[i].picFile)
            cnt++;
        }
    } else {
        return
    }
};

/**
 * 인근매각물건을 조회해오는 함수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.13.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.getAroundGds = function (dvsCd) {

    let url = "";
    if (dvsCd === "DSPSL") { //인근매각 물건
        url = '/pgj/pgjsearch/selectAroundDspslGds.on'
    } else if (dvsCd === 'PROG') { //인근진행 물건
        url = '/pgj/pgjsearch/selectAroundProgGds.on'
    }
    // 인근매각물건 조회 결과값
    let result;
    // 해당사건 (시/도 코드. 시/군/구) 코드
    const dspslGdsDxdyInfo = dma_result.get('dspslGdsDxdyInfo');
    // 해당사건 매각물건용도코드
    const gdsDspslObjctLst = dma_result.get('gdsDspslObjctLst');

    let temp = {
        csNo: scwin.param.csNo,
        cortOfcCd: scwin.param.cortOfcCd,
        dspslGdsSeq: scwin.param.dspslGdsSeq,
        rletCarDvsCd: "0",
        rprsAdongSdCd: !scutilo.isEmpty(gdsDspslObjctLst[0].rprsAdongSdCd) ? gdsDspslObjctLst[0].rprsAdongSdCd : "xxx",
        rprsAdongSggCd: !scutilo.isEmpty(gdsDspslObjctLst[0].rprsAdongSggCd) ? gdsDspslObjctLst[0].rprsAdongSggCd : "xxx",
        auctnGdsUsgCd: !scutilo.isEmpty(dspslGdsDxdyInfo.auctnGdsUsgCd) ? dspslGdsDxdyInfo.auctnGdsUsgCd : "xxx"
    }

    let param = JSON.stringify(temp);
    let options = {
        action: url,
        mode: 'synchronous',
        method: 'POST',
        requestData: param,
        mediatype: 'application/json',
        success: function (e) {
            result = e.responseJSON.data.result;
        }
    }
    // 조회 시작
    $w.ajax(options)

    return result;
}

/**
 * 인근매각물건사례 탭이동시 해당하는 탭의 정보를 보여준다.
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.13.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.tac_aroundGdsExm_onchange = function (tabID, idx, userTabID) {
    if (idx === 1) { //인근매각물건
        grp_msgBox.hide();
        const aroundDspslGdsResult = scwin.getAroundGds('DSPSL');
        aroundDspslGdsResult.forEach(data => {
            let printLst = "";
            data.srnSaNo = `${data.jiwonNm}<br />${data.saNo.substring(0, 2)}**타경*******`;
            data.gamevalAmt = scutilo.getCommaFmt(data.gamevalAmt);
            data.maeGiil = scdateo.getFmtDate(data.maeGiil, '.').slice(0, -3);
            data.maemulUtilCd = pgjUtil.getSTGcodeSystemNm("PGJ", 'AUCTN_GDS_USG_CD', data.maemulUtilCd)
            if (data.addrGbncd === "R") {
                printLst = `${data.rd1Nm} ${data.rd2Nm}`
                printLst += !scutilo.isEmpty(data.rdEubMyun) ? ` ${data.rdEubMyun}` : "";
                printLst += ` ${data.rdNm}<br />`
            } else {
                printLst = `${data.hjguSido} ${data.hjguSigu} ${data.hjguDong}<br />`
            }
            printLst += data.userLstPrint;
            data.printLst = printLst;
            data.maeAmt = scutilo.getCommaFmt(data.maeAmt);
        });
        dlt_srchResult.setJSON(aroundDspslGdsResult)

        //같은 사건 번호경우는 셀병합
        if (!scutilo.isEmpty(aroundDspslGdsResult)) {
            let rowSeq = 0;
            let rSpnCnt = 1;
            let seqTemp = 0;
            for (let i = 0; i < aroundDspslGdsResult.length; i++) {
                seqTemp++
                if (i + 1 === aroundDspslGdsResult.length) {
                    continue;
                }
                if (aroundDspslGdsResult[i].saNo === aroundDspslGdsResult[i + 1].saNo) {
                    rSpnCnt++
                    grd_aroundDspslGds.mergeCell({ "rowIndex": rowSeq, "colIndex": 0, "colSpan": 1, "rowSpan": rSpnCnt })
                    grd_aroundDspslGds.mergeCell({ "rowIndex": rowSeq, "colIndex": 1, "colSpan": 1, "rowSpan": rSpnCnt })
                    grd_aroundDspslGds.mergeCell({ "rowIndex": rowSeq, "colIndex": 3, "colSpan": 1, "rowSpan": rSpnCnt })
                    grd_aroundDspslGds.mergeCell({ "rowIndex": rowSeq, "colIndex": 4, "colSpan": 1, "rowSpan": rSpnCnt })
                    grd_aroundDspslGds.mergeCell({ "rowIndex": rowSeq, "colIndex": 5, "colSpan": 1, "rowSpan": rSpnCnt })
                } else {
                    rSpnCnt = 1;
                    rowSeq = seqTemp;
                }
            }
        }
        grp_msgBox.show("");
        tbx_dspslGdsGdn.setValue(scwin.aroundDspsltxt);
    } else if (idx === 2) { // 인근진행물건
        const aroundProgGdsResult = scwin.getAroundGds('PROG');

        if (!scutilo.isEmpty(aroundProgGdsResult)) {
            dlt_aroundProgGds.removeAll();
            aroundProgGdsResult.forEach((data, idx) => {
                if (!(scwin.param.cortOfcCd === data.boCd
                    && scwin.param.csNo === data.srnSaNo
                    && scwin.param.dspslGdsSeq === data.maemulSer)) {
                    dlt_aroundProgGds.insertRow(idx);
                    //사건 커스텀 태그
                    let csNoTag = new String();
                    //주소 커스텀 태그
                    let stTag = new String();
                    //최저매각가격 커스텀 태그
                    let lwsPrcTag = new String();
                    // 유찰 커스텀 태그
                    let flbd = new String();
                    csNoTag = `<div><a href="#" onclick="moveCsDtlPage(${idx})">${data.jiwonNm}<br />`
                    csNoTag += `<text class="fc_blue5 fwb">${data.srnSaNo}<text></a><br />`
                    if (!scutilo.isEmpty(data.dupSaNo)) {
                        csNoTag += `${data.dupSaNo}<br />(중복)<br />`
                    }
                    if (!scutilo.isEmpty(data.byungSaNo)) {
                        csNoTag += `${data.byungSaNo}<br />(병합)<br />`
                    }
                    csNoTag += `</div>`
                    dlt_aroundProgGds.setCellData(idx, "csNo", csNoTag);
                    dlt_aroundProgGds.setCellData(idx, "cortOfcCd", data.boCd);
                    dlt_aroundProgGds.setCellData(idx, "srnSaNo", data.srnSaNo);
                    dlt_aroundProgGds.setCellData(idx, "dspslGdsSeq", data.maemulSer);
                    stTag = `<div><a href="#" onclick="moveDtlPage(${idx})">${data.userStPrint}</a><br />`
                    stTag += `${data.userLstPrint}</div>`;
                    dlt_aroundProgGds.setCellData(idx, "printSt", stTag);
                    dlt_aroundProgGds.setCellData(idx, "dspslGdsRmk", !scutilo.isEmpty(data.mulBigo) ? data.mulBigo : "");
                    if (!scutilo.isEmpty(data.notifyMinmaePrice2) && data.notifyMinmaePrice2 !== '0') {
                        lwsPrcTag += `<div><img src="/pgj/cm/images/contents/number_01.gif" alt="오전" />${scutilo.getCommaFmt(data.notifyMinmaePrice1)}<br />`
                        lwsPrcTag += `<img src="/pgj/cm/images/contents/number_02.gif" alt="오후" />${scutilo.getCommaFmt(data.notifyMinmaePrice2)}</div>`
                    } else {
                        lwsPrcTag += `${scutilo.getCommaFmt(data.notifyMinmaePrice1)}`
                    }
                    dlt_aroundProgGds.setCellData(idx, "aeeEvlAmt", !scutilo.isEmpty(data.gamevalAmt) ? scutilo.getCommaFmt(data.gamevalAmt) : 0);
                    dlt_aroundProgGds.setCellData(idx, "lwsDspslPrc", lwsPrcTag);
                    dlt_aroundProgGds.setCellData(idx, "deptNm", data.jpDeptNm);
                    dlt_aroundProgGds.setCellData(idx, "dspslDxdyYmd", !scutilo.isEmpty(data.maeGiil) ? scdateo.getFmtDate(data.maeGiil, ".") : "");
                    dlt_aroundProgGds.setCellData(idx, "auctnGdsUsgCd", pgjUtil.getSTGcodeSystemNm('PGJ', 'AUCTN_GDS_USG_CD', data.maemulUtilCd));
                    if (data.yuchalCnt === "0") {
                        flbd = '신건'
                    } else {
                        flbd = `유찰<br />${data.yuchalCnt}회`
                    }
                    dlt_aroundProgGds.setCellData(idx, "csProgStatCd", flbd);
                }
            });
        }

        //인근매각물건사례
        grp_msgBox2.show("");
        tbx_dspslProgGds.setValue(scwin.aroundDspsltxt);
    }
};

