/**
 *
 *
 * 매각물건명세서 목로 수 입력후 내부 pdf 뷰어 호출
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.19.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_insertDspslGdsSpecLogInfo_submitdone = function ({ responseJSON }) {
    if (responseJSON.status === 200) {
        // 요청 방식이 AS-IS와 동일
        try {
            let url = dma_dspslSpcfcInfo.get("url")
            const data = {
                encParam: dma_dspslSpcfcInfo.get("encParam"),
                pspTkn: "NA", // 로그인 관련 처리 제외
                pspSid: "NA", // sid 관련 처리 제외
            };
            // 057EB645AC14102448949803C8101F77	000230	20132110000002
            let queryParam = `?paramData=${WebSquare.text.BASE64Encode(com.str.serialize(data))}`;
            // let queryParam =`?paramData=${data}`;
            window.open(url + queryParam, "소송문서뷰어");
        } catch (e) {
            scutilo.showMsg(scglblo.MSG.ERROR, e.message);
        }
    } else {
        scutilo.showMsg(scglblo.MSG.ERROR, "물건매각명세서가 존재하지 않습니다.");
    }
};


