scwin.btn_landUtilPlan_onclick = function (e) {
    let id = this.id;
    const pnuNoCtt = $p.getComponentById(id).getUserData('pnuNoCtt');
    if (scutilo.isEmpty(pnuNoCtt)) {
        scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pgjmsg.PGJ.W_0052));
        return
    } else if (pnuNoCtt.length !== 19 || isNaN(pnuNoCtt)) {
        scutilo.showConfirm(scglblo.MSG.CONFIRM, pgjmsg.PGJ.C_0010, function (result) {
            if (result) { //본 번호의 길이가 맞지않거나 유효하지 않은 번호일경우 온나라포털 호출
                let url = window.open("https://seereal.lh.or.kr/", "", "");
                url.focus();
                return;
            } else {
                return;
            }
        })
    }
    const popUpId = "landUtilPlanPopUp"
    // 팝업 id중복체크 후 팝업창 오픈
    if (pgjUtil.popupDpcnChk(popUpId)) {
        scwin.landUtilPlanPopUp(pnuNoCtt, popUpId);
    } else {
        return;
    }

};

