    if (carUnqNo.length === 14) {
        let popUpId = 'rgstryPopUp'
        if (pgjUtil.popupDpcnChk(popUpId)) {
            scwin.rgstryPopUp(carUnqNo)
        } else {
            return;
        }
    }
};


