/**
 * 뒤로가기 버튼 클릭시 뒤로가기 이동
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.22.   나해준                    [NELS]최초 생성
 *  2025.07.23.   강은숙                    [25A-PGJ-0018] 매각공고에서 물건조회시 오류 개선
 *  2025.08.06.   강은숙                    [25A-PGJ-0020] 매수보증금의 표시 개선
 *  2025.12.26.   공태은                    [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
 * ============= ============ ==========================
 */
scwin.btn_prevBtn_onclick = function (e) {

    let path = '';
    let detailInfo = {};
    let obj = {
        "dataObject": {
            "type": "json",
            "name": "param",
            "data": {}
        }
    };
    detailInfo = {
        sideDvsCd: scwin.param.srchInfo.sideDvsCd,
        cortOfcCd: scwin.param.cortOfcCd,
        csNo: scwin.param.csNo,
        prevInfo: {
            prevPgmId: scwin.prevPgmId
            , pageNum: scwin.pageNum
        },
        srchInfo: scwin.param.srchInfo
    }

    switch (scwin.prevPgmId) {
        case 'PGJ143M01':
            path = '/pgj/ui/pgj100/PGJ143M01.xml';
            break;
        /* [25A-PGJ-0018] 매각공고에서 물건조회시 오류 개선  */
        case 'PGJ143M02':
            path = '/pgj/ui/pgj100/PGJ143M02.xml';
            break;
        /* [25A-PGJ-0020] 매각공고에서 넘어온 경우 이전으로 갈수있게 수정(취소정정공고 화면)  */
        case 'PGJ143M03':
            path = '/pgj/ui/pgj100/PGJ143M03.xml';
            break;
        case 'PGJ151F01':
            path = '/pgj/ui/pgj100/PGJ151M01.xml';
            break;
        case 'PGJ15BM01':
            path = '/pgj/ui/pgj100/PGJ151M01.xml';
            break;
        case 'PGJ151M01':
            path = '/pgj/ui/pgj100/PGJ151M01.xml';
            break;
        // 2025.12.26. 공태은 [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
        case 'PGJ154M02':
            path = '/pgj/ui/pgj100/PGJ154M02.xml';
            break;
        case 'PGJ155M01':
            path = '/pgj/ui/pgj100/PGJ155M02.xml';
            break;
        case 'PGJ156M01':
            path = '/pgj/ui/pgj100/PGJ156M02.xml';
            break;
        case 'PGJ157M01':
            path = '/pgj/ui/pgj100/PGJ157M02.xml';
            break;
        case 'PGJ158M01':
            path = '/pgj/ui/pgj100/PGJ158M02.xml';
            break;
        case 'PGJ159M01':
            path = '/pgj/ui/pgj100/PGJ159M01.xml';
            break;
        case 'PGJ111M01':
            $p.url(`/pgj/ui/pgj100/PGJ111M01.xml`);
            break;
        case 'PGJ192M01':
            $p.url(`/pgj/ui/pgj100/PGJ192M01.xml`);
            break;
        case 'PGJ193M01':
            path = '/pgj/ui/pgj100/PGJ193M01.xml';
            break;
        // 2025.12.26. 공태은 [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
        case 'PGJ195M02':
            path = '/pgj/ui/pgj100/PGJ157M02.xml';
            break;
    }
    obj.dataObject.data = detailInfo
    $p.main().wfm_mainFrame.setSrc(path, obj);
};

/**
 * 시건상세 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.22.   나해준       [NELS]최초 생성
 *  2023.12.26.   공태은       [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
 * ============= ============ ==========================
 */
scwin.btn_moveCsDtl_onclick = function (e) {
    const baseInfo = dma_result.get('csBaseInfo');
    let srchInfo = scwin.param.srchInfo;
    srchInfo.sideDvsCd = srchInfo.sideDvsCd;

    // 2025.12.26. 공태은 [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
    if(srchInfo.sideDvsCd == '3'){
        srchInfo.menuNm = '자주쓰는검색';
    }else{
        srchInfo.menuNm = scwin.menuNm;
    }

    let obj = {
        "dataObject": {
            "type": "json",
            "name": "param",
            "data": {
                srchInfo
                , cortOfcCd: baseInfo.cortOfcCd
                , csNo: baseInfo.csNo
                , prevInfo: {
                    prevPgmId: scwin.prevPgmId
                    , pageNum: scwin.pageNum
                }

            }
        }
    };
    $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ15AF01.xml', obj);

};

/**
 *
 * 사건 상세 페이지 이동(인근진행물건)
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.03.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
function moveCsDtlPage(index) {
    const info = scwin.param;
    const csNo = dlt_aroundProgGds.getCellData(index, 'srnSaNo');
    const cortOfcCd = dlt_aroundProgGds.getCellData(index, 'cortOfcCd');
    const dspslGdsSeq = dlt_aroundProgGds.getCellData(index, 'dspslGdsSeq');
    const srchInfo = info.srchInfo;
    const pgmId = "PGJ151M01";
    let obj = {
        "dataObject": {
            "type": "json",
            "name": "param",
            "data": {
                csNo
                , cortOfcCd
                , dspslGdsSeq
                , prevInfo: { prevPgmId: pgmId }
                , srchInfo: info.srchInfo
            }
        }
    };

    $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ15AF01.xml', obj);
}

/**
 *
 * 주소 상세 페이지 이동(인근진행물건)
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.03.   나해준       [NELS]최초 생성
 *  2025.12.26.   공태은       [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
 * ============= ============ ==========================
 */
function moveDtlPage(index) {
    const info = scwin.param;
    const csNo = dlt_aroundProgGds.getCellData(index, 'srnSaNo');
    const cortOfcCd = dlt_aroundProgGds.getCellData(index, 'cortOfcCd');
    const dspslGdsSeq = dlt_aroundProgGds.getCellData(index, 'dspslGdsSeq');
    const srchInfo = info.srchInfo;
    const pgmId = scwin.pgmId;
    // 2025.12.26. 공태은 [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
    let obj = {
        "dataObject": {
            "type": "json",
            "name": "param",
            "data": {
                csNo
                , cortOfcCd
                , dspslGdsSeq
                , pgmId
                , prevInfo: { prevPgmId: pgmId }
                , srchInfo
            }
        }
    };

    $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ15BM01.xml', obj);

}

/**
 *  Map 팝업 window 타입 설정
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.01.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.openMap = function (e) {

    /********* Popup Settings *********/
    const winW = window.innerWidth;
    const winH = window.innerHeight;

    /* default popup size */
    const popupW = winW - 300;
    const popupH = winH - 100;

    const popupX = (winW / 2) - (popupW / 2);
    const popupY = (winH / 2) - (popupH / 2);

    const options = {
        id: "gdsMap",
        type: "browser",
        popupName: "지도",
        top: popupY,
        left: popupX,
        width: popupW,
        height: popupH,
        modal: false
    };


    paramObj = {};
    paramObj.pgmId = scwin.pgmId;
    let id = this.id;
    const x = $p.getComponentById(id).getUserData('x');
    const y = $p.getComponentById(id).getUserData('y');
    const baseInfo = dma_result.get('csBaseInfo');
    const dspslGdsDxdyInfo = dma_result.get('dspslGdsDxdyInfo');
    paramObj.info = {
        csNo: baseInfo.userCsNo,
        cortOfcCd: baseInfo.cortOfcCd,
        dspslGdsSeq: dspslGdsDxdyInfo.dspslGdsSeq,
        x: x,
        y: y
    };

    com.win.openPopup("/pgj/ui/pgj100/PGJ152F00.xml", options, paramObj);
}

scwin.printEvent = function () {
    let paramJSON = {};
    paramJSON.html = document.getElementById($p.getComponentById('grp_contests').id).innerHTML;

    var dataObject = {
        type: "json",
        data: paramJSON,
        name: "paramObj"
    };

    /* default popup size */
    const winW = window.innerWidth;
    const winH = window.innerHeight;
    const popupW = 1200;
    const popupH = 700;

    const popupX = (winW / 2) - (popupW / 2);
    const popupY = (winH / 2) - (popupH / 2);

    // 팝업의 옵션
    var options = {
        id: 'print',					// 팝업ID
        type: "browserPopup",			// 팝업 타입(wframePopup,browserPopup)
        width: popupW,				// 팝업 가로사이즈
        height: popupH,			// 팝업 세로사이즈
        top: popupY,					// 팝업 top위치
        left: popupX,				// 팝업 left위치
        popupName: "프린트",				// 팝업 Name
        modal: false,					// 부모창이 안움직임(true)/부모창이 움직임(false)
        useIFrame: true,
        dataObject: dataObject
    };

    $p.openPopup("/pgj/ui/pgj100/PGJPrintContainer.xml", options);
}

